/* Hooks: a U6 system, or the U6 cases of a shared verb, moved whole into the function U6's table names.
 * NULL = the game has no such rule yet (SE and MD fill theirs in as their GAME.EXEs are read). */
typedef struct GameLayer {
    const GameObjs *on;
    /* verbs */
    void (*talk)(int id);                                       /* T)alk to an actor (usecode_vm.md) */
    int  (*use_at)(world_t *w, int tx, int ty, int dx, int dy, int idx);   /* U)se: what comes before the use switch (vehicles, mounts, wells); -1 = none of these */
    int  (*use)(int idx);                                       /* U)se a thing on the map: the game's use switch (usecode_use.md) */
    int  (*usable)(int on);                                     /* U)se finds something to use under a thing that is not (usecode_use.md) */
    uint8_t use_under;                                          /* a usable thing under an unusable one answers (U6); SE doesn't look (se_use.md §1) */
    const char *nothing, *unusable;                             /* U)se's words for an empty tile and a thing it can't use; NULL = U6's */
    int  (*bot_door)(const wobj_t *o);                          /* the bot's door list (bot_harness.md): 0-3 open, 4-7 shut, 8+ locked; -1 = not a door */
    int  (*use_ground)(world_t *w, int tx, int ty, int n);      /* U)se on a tile with nothing on it, in reach: the map tile decides (se_use.md §1); n = the echo so far */
    int  (*use_pack)(world_t *w, int on);                       /* U)se a thing in the pack or readied (usecode_use.md) */
    int  (*rides)(void);                                        /* the leader rides one of the game's creatures (SE's turtle): U)se on itself is the use */
    /* movement */
    int  (*veh_move)(world_t *w, int dx, int dy);               /* a step aboard the game's own vessel: its cost, 0 = no move; -1 = U6's vessels (vehicles.md) */
    int  (*lead_step)(world_t *w, int dx, int dy);              /* the leader's step by the game's own rule (a rider): 1 moved, 0 blocked; -1 = on foot */
    int  (*can_enter)(const world_t *w, int x, int y, int on);  /* may a creature of obj_n on step onto (x,y) by the game's rule; -1 = by its movement type (combat.md §7c) */
    int  (*push_select)(world_t *w, int dx, int dy);            /* M)ove: pick the thing on the map; NULL = U6's (usecode_use.md) */
    int  (*push_to)(world_t *w, int dx, int dy);                /* M)ove's "To ": push it a tile; NULL = U6's */
    int  (*move_to)(world_t *w, int dx, int dy);                /* M)ove's "To " for a thing in the pack, at the crosshair; NULL = U6's (equipment.md §5) */
    int  (*move_into)(world_t *w, int t);                       /* M)ove's "To " a thing in the pack: into it or out of it; NULL = U6's */
    int  (*store)(int ci, int i);                               /* may map container ci take world object i; NULL = U6's can_store */
    int  (*drop_ok)(const world_t *w, int tx, int ty, int top, int row);   /* D)rop: may pack row land at (tx,ty), top the first thing there; NULL = U6's (usecode_use.md) */
    int  (*dropped)(world_t *w, int slot, int top, int far, int n);  /* D)rop: what happens where it lands (lost, broken, into a container, a blast); 1 = all done; NULL = U6's */
    const char *notposs;                                        /* D)rop's refusal; NULL = U6's "Not possible" */
    uint8_t asks_count;                                         /* a stack asks "How many?" first (usecode_use.md) */
    uint8_t stagger8;                                           /* past 3 drinks: 1 in 2, a step one of eight ways (SE, se_use.md §5o); 0 = U6's 3 in 4, any way */
    const char *see;                                            /* L)ook's opening words (usecode_use.md, the look line) */
    int16_t ol_talk, ol_talk_hi;                                /* objlist offsets of the talk flags (0-7, 8-15); 0 = U6's (converse.md §6c) */
    int  (*rest)(world_t *w);                                   /* R)est: the refusals, the camp, the meal, the sleep (rest.md) */
    void (*rest_tick)(world_t *w);                              /* a step of the night, when the game has its own (se_rest.md §5) */
    int  (*rest_key)(world_t *w,int a);                         /* its prompts' keys (se_rest.md §2) */
    void (*cast)(void);                                         /* C)ast: the spellbook page (magic_skills.md §6) */
    /* the pack */
    uint8_t gold_pool;                                          /* the party's gold is one pool (SE/MD), not coins carried in the packs (U6) */
    int  (*ready_ok)(int a,int on,int n);                       /* may actor a ready obj_n at all (SE's modern weapons); 0 = refused, the words said after echo n */
    void (*ready_on)(int a,int on);                             /* a readied thing takes effect (equipment.md §8) */
    void (*ready_off)(int a,int on);                            /* a readied thing comes off */
    void (*unreadied)(int a,int on);                            /* it is back in the pack (SE's flintlock keeps its load) */
    int  (*ready_fr)(int a,int on);                             /* the frame a readied thing shows (SE's loaded flintlock); NULL = 0 */
    void (*ready_tick)(void);                                   /* what readied things do each turn */
    int  (*theft)(const world_t*w,int idx);                     /* taking this is theft (usecode_use.md, Theft); 0 = never */
    /* the clock */
    void (*wind_tick)(int level);                               /* the wind changes, each minute (wind.md §1) */
    void (*burn_tick)(const world_t*w);                         /* torch fuel and keg fuses, each turn (usecode_use.md) */
    void (*npc_torches)(const world_t*w);                       /* NPCs light and douse torches on the hour (usecode_use.md) */
    void (*moongates)(const world_t*w);                         /* natural moongates follow the moons (moongates.md §2) */
    void (*eggs)(const world_t *w, int teleport);               /* eggs near the party hatch what they hold (eggs.md §2) */
    /* combat */
    int  (*max_mana)(int i);                                    /* magic points by what the actor is (magic_skills.md §3); none = 0 */
    void (*touch)(int att,int def);                             /* what a creature's blow does besides harm: dragging, dissolving, robbing, poison (combat.md) */
    void (*shot_spend)(const world_t*w,int att,int wobj,int sx,int sy,int lx,int ly,int id);   /* what a shot uses up or leaves behind: arrows, bolts, thrown things, wands (combat.md) */
    void (*hazard)(int a,int t);                                /* what a harmful tile or field does to one on it, by tile number (combat.md §5) */
    uint8_t hazard_obj_first;                                   /* SE: the things on a tile are looked at before the ground (se_combat.md §6) */
    int  (*foe_cast)(const world_t*w,int i,int tid,int tx,int ty);   /* a hostile's charge roll and spell (combat.md §7b); 1 = cast */
    int  (*atk_check)(const world_t*w,int att,int*wobj,int tx,int ty,int dist,int*ranged,int stage,int n);   /* the game's own refusals around a blow: stage 0 the player's before the name, 1 the blow's (SE, se_combat.md §3a); -1 = strike on, else its cost; NULL = U6's range and ammunition */
    int  (*hit_rule)(int att,int wobj,int def,int role);         /* a hit by the game's own rule (SE's spear, staff, Myrmidex); -1 = the roll */
    int  (*blow)(int att,int def,int oi,int wobj,int*wm);       /* what a landed blow does instead (def<0: on object oi), or its damage *wm; 1 = all done */
    int  (*wound_to)(int def);                                  /* who takes a wound (SE's queen, the unharmed); -1 = nobody */
    int  (*wound_own)(int att,int def,int dmg);                 /* a wound the game takes over entirely (SE's orchids); 1 = done */
    int  (*wt_act)(const world_t*w,int i,int wt);               /* a worktype the game does its own way (SE's orchid heads); 1 = done */
    const char*const*cmode_name;                                 /* the combat modes' names by worktype-2 (NULL: U6's) */
    int  (*cmode_next)(int m);                                  /* the mode button's next mode (NULL: U6's 2..8) */
    void (*status_tick)(void);                                  /* the game's own wear-offs (SE's invocations); U6's protect/curse/charm rolls then stay out */
    int  (*big_step)(const world_t*w,int i,int d);              /* a step the game takes its own way (SE's big creatures); -1 = the ordinary step */
    int  (*actor_tile)(int i);                                  /* the tile an actor shows as it stands (SE's big creatures); -1 = by facing and gait */
    int  (*look)(world_t*w,int dx,int dy);                     /* L)ook on the map the game's own way (SE); NULL = U6's */
    void (*look_pack)(const invitem_t*it);                      /* L)ook at a carried thing (SE); NULL = U6's */
    int  (*get)(world_t*w,int dx,int dy);                       /* G)et the game's own way (SE); NULL = U6's */
    int  (*counted)(int on);                                    /* named with a count (SE's list); NULL = U6's */
    int  (*sleep_body)(int i);                                  /* what a sleeper lies as when no sleep table names it (obj | frame<<10); 0 = as it stands */
    uint8_t wake_odds;                                          /* a sleeper wakes 1 time in this many per turn; 0 = 16 */
    uint8_t no_scatter;                                         /* a missed shot flies at its target still (SE); 0 = it lands beside (U6) */
    void (*death_words)(int def);                               /* the words for any death (SE, se_combat.md §3d); NULL = U6's "killed!" for a blow */
    int  (*dying)(int id,int temp);                             /* what a death does before its remains (the story, a rider, blood); 1 = it leaves nothing and keeps its things */
    int  (*kill_exp)(int v);                                    /* the experience for slaying actor v; NULL = U6's (combat.md §3) */
    uint16_t exp_cap;                                           /* experience stops here (SE 9999); 0 = 65535 */
    void (*avatar_death)(world_t*w);                            /* the Avatar falls: U6's KAL LOR and Lord British's recall (combat.md §3d); none = the game ends */
    /* the end */
    void (*ending)(world_t *w);                                 /* the game is won: its ending (design/ending.md); none = play stops */
} GameLayer;
