static int32_t        g_objlist_off;          /* objlist offset within the template (-1 = none) */

/* runtime-loaded conversation + portrait libraries (4-byte LE offset tables) */
/* CONVERSE.A/.B + PORTRAIT.A/.B: 4-byte-offset libraries (docs/formats/library.md), either RESIDENT
 * (whole file in the pool, big-RAM machines) or ON DEMAND (only the offset index in RAM; an entry is
 * read into a bounce buffer when a conversation/portrait needs it — 4 MB machines). Decided at boot
 * from the free pool (memory_streaming.md). Entries are tiny (largest 4.3 KB) so on-demand costs one
 * Fopen/Fseek/Fread per talk. */
#define LIB_MAXENT 160                     /* CONVERSE.B has 125 entries; PORTRAIT.A 98 */
#define LIB_BOUNCE 8192                    /* >= the largest U6 entry (4.3 KB) */
typedef struct { const char *name; const uint8_t *data; int32_t len; int count; int32_t maxent; uint8_t idx[LIB_MAXENT*4]; } lib_t;
enum { LIB_CONVA=0, LIB_CONVB, LIB_PORTA, LIB_PORTB, LIB_N };
static lib_t   g_lib[LIB_N] = {{"CONVERSE.A"},{"CONVERSE.B"},{"PORTRAIT.A"},{"PORTRAIT.B"}};
static uint8_t g_lib_bounce[LIB_BOUNCE];
static int     g_libs_resident;            /* 1 = all four libraries resident, 0 = on demand */
static int     g_libs_ok;                  /* all four opened (resident or indexed) */
static int            g_countA;            /* CONVERSE.A entry count (NPC split)  */
static int            g_talking;           /* 1 = a conversation is on screen     */
static int            g_have_pc;           /* 1 = g_cur_portrait holds a portrait  */
static char           g_talk_name[32];     /* current NPC's name (from the VM)    */
static uint8_t        g_cur_portrait[PW*PH];/* decoded 56x64 portrait             */
static uint8_t        g_script_buf[16384]; /* decompressed conversation for the VM*/
static int            g_hour;              /* current game hour 0-23 (from clock)  */
static int            g_minutes;           /* current minute-of-day (for the sky bar) */
static int            g_await_input;       /* 1 = VM paused (CVM_ASK), typing a reply */
static char           g_inbuf[CVM_INPUT];  /* the keyword/number being typed       */
static int            g_inlen;

/* object verbs + inventory (look / get / use) */
#define MAXWOBJ 12000
static wobj_t         g_wobj[MAXWOBJ];      /* mutable world objects (alive flag)   */
static uint8_t        g_wtemp[MAXWOBJ/8];    /* bit set = created at runtime (no save record): freed, never reconciled */
static objworld_t     g_ow;
static const char    *g_looktbl[2048];     /* tile -> name (into the pack's blob)  */
static const uint8_t *g_basetile;          /* 1024 x u16 LE: obj_n -> base tile    */
/* tile animation (ANIMDATA, U6WD): animated tile slots are blank in the tileset;
 * each is filled from src..src+nframes-1, cycling on g_anim_ctr. (animdata.md) */
static int16_t        g_anim_idx[2048];    /* tile -> anim entry index, or -1      */
static uint16_t       g_anim_src[32];      /* per entry: source-frame base tile     */
static uint8_t        g_anim_n[32];        /* per entry: number of frames           */
static int            g_nanim;
static uint32_t       g_anim_ctr;          /* current animation step                */
static int            g_view_has_anim;     /* 1 if an ANIMDATA tile is in the map view (perf gate) */
static uint8_t        g_objanim[1024];     /* per-obj_n frame count (0=static): fire/flame objects cycle frame_n (U6WE) */
static uint8_t        g_tflags[2048];       /* tileflags2 by tile: bit4 Foreground, bits6-7 size (U6WF) */
static uint8_t        g_tflags1[2048];      /* tileflags1 by tile: bit1 Impassable, bit2 Wall (U6WG) */
/* bit per tile, sparse: 135 and 100 pages in the whole of U6; the stores hold about 2.5x that */
static uint8_t        g_blocked_store[340*SB_PAGE_BYTES], g_sightblk_store[256*SB_PAGE_BYTES];
static sparsebits_t   g_blocked ={ .store=g_blocked_store,  .cap=340 };   /* impassable OBJECT on tile */
static sparsebits_t   g_sightblk={ .store=g_sightblk_store, .cap=256 };   /* sight-blocking OBJECT on tile (closed door etc.) for LOS */
/* MAGIC field-tile layer (docs/rules/magic_skills.md §5a): temporary fire/poison/
 * sleep/energy fields placed by spells. kind: 0 fire, 1 poison, 2 sleep, 3 energy(block). */
#define MAXFIELDS 64
typedef struct { uint16_t x, y, tile, obj_n; uint8_t kind, turns; } field_t;
static field_t        g_fields[MAXFIELDS];
static int            g_nfields=0;
static uint8_t        g_asleep[256];          /* >0 = actor is asleep for N turns (sleep field) */
/* spatial bucket index over world objects (16x16-tile buckets, 64x64 grid): compose visits
 * only the buckets overlapping the view instead of scanning all ~8000 objects every frame.
 * CSR layout: g_obkt_idx[g_obkt_start[b] .. g_obkt_start[b+1]) = object indices in bucket b.
 * Rebuilt in build_blocked (the "objects changed" hook). */
#define OBKT 64
static uint16_t       g_obkt_start[OBKT*OBKT+1];
static uint16_t       g_obkt_idx[MAXWOBJ];
/* FOREGROUND-only parallel bucket index: the same CSR layout but containing ONLY objects that can draw a
 * Foreground (top-pass) tile. The per-frame pass-1 (draw_view_objects pass 1) redraws foreground OVER the
 * actors every frame; scanning all in-view objects to find the ~handful that are foreground cost ~37 ms
 * (measured: 77 objects visited, 4 actually blitted, on the cacheless 68000). Iterating this sparse subset
 * instead cuts that to the foreground objects only. Membership is computed once per object in build_blocked
 * via obj_is_fg (complete over multi-tile + ANIMDATA/objanim frames); fg_index_selftest proves == full scan. */
static uint16_t       g_fgbkt_start[OBKT*OBKT+1];
static uint16_t       g_fgbkt_idx[MAXWOBJ];
/* LIGHT/SIGHT-only parallel bucket index: objects that emit light OR block sight. compute_light and
 * compute_visibility each scan the view's objects every non-cached (scroll) frame to find the handful of
 * emitters / sight-blockers — ~9 ms per scan. Iterating this sparse subset instead cuts that to the
 * relevant objects. Built in build_blocked via obj_is_lightsight (complete over ANIMDATA/objanim frames). */
static uint16_t       g_lsbkt_start[OBKT*OBKT+1];
static uint16_t       g_lsbkt_idx[MAXWOBJ];

/* Incremental map-scroll: g_tmp_map caches the STATIC compose layer (base tiles + lower-pass
 * objects, no actors/foreground/lighting). On a 1-tile walk it is memmove-scrolled and only the
 * lead 2-cell band is recomposed; actors, foreground objects, roofs and lighting are redrawn
 * full per frame (so no actor-erase or shifted-light artifacts). See docs/design/performance.md. */
#define TMP_T (VT*16)
static uint8_t        g_tmp_map[TMP_T*TMP_T];
static int            g_tmp_valid=0, g_tmp_px=-30000, g_tmp_py=-30000;
static int            g_avatar_hide;   /* vehicles: 1 = draw no avatar sprite (the boat IS the visual) */
static uint16_t       g_avatar_ovr;    /* vehicles: nonzero = draw this tile at centre (horse-with-rider) */
static int            g_idle_allow=0;  /* set by the caller ONLY for an animation-tick recompose (view fixed,
                                        * nothing but animation changed) -> enables the idle-incremental static
                                        * path. Cleared for every action/scroll compose (which may mutate static
                                        * tiles) so those keep the full rebuild. See predim_compose_static. */
/* Incremental PREDIM: g_dimmed_map is the DIMMED static layer (g_tmp_map dimmed by the per-cell
 * light), persisted across frames and memmove-scrolled in lockstep with g_tmp_map. Only cells
 * whose light CHANGED frame-to-frame (the view-anchored avatar globe's moving arc + emitters that
 * crossed the view edge) plus the freshly-revealed lead band are re-dimmed; every other cell is
 * reused from the shifted buffer. So the free block-copy present of PREDIM is kept, but the 598 ms
 * full re-dim collapses to edge+globe work. g_dm_light caches last frame's per-cell light (0..255,
 * vis already folded in as 0) to detect the changed cells. See docs/rules/lighting.md Stage F. */
static uint8_t        g_dimmed_map[TMP_T*TMP_T];
static uint8_t        g_dm_light[VT*VT];
static int            g_dm_valid=0;
/* cell-granular clip rect for draw_cell (default = whole view); recompose_band narrows it so a
 * band redraw composes only band cells byte-identically (multi-tile bleed into the band lands;
 * everything else is rejected per-cell). */
static int            g_clip_x0=0,g_clip_y0=0,g_clip_x1=VT,g_clip_y1=VT;
static const uint8_t *g_pd_objgate=0;   /* incremental static-object pass: if set, a per-cell dirty mask —
                                         * draw_cell composites ONLY dirty cells (clean cells keep their
                                         * already-shifted object pixels). NULL = draw every cell. */
static const uint8_t *g_pd_dyngate=0;   /* idle persistent-g_ptmp: if set, a per-cell DYNAMIC-dirty mask that
                                         * gates ONLY the planar dynamic blit (rdr_pdyn_cell -> g_ptmp) — the
                                         * chunky copy stays full so the INV2 verify still sees a whole tmp.
                                         * NULL = blit every cell (the full-copy path). See compose_map idle. */
static sparsebits_t   g_indoor;               /* bit per tile: INDOOR (under a roof) -> low ambient (U6WI); store sized at load */
static int            tile_is_indoor(int x,int y){ return sb_get(&g_indoor,x,y); }
static const uint8_t *g_rtiles;               /* roof tileset (n*256, 255=transparent), points into pak (U6WK) */
static int            g_nrtiles;
static const uint8_t *g_roofmap;              /* g_nroof x {u32 pos=y*1024+x BE, u16 dense idx BE}, sorted by pos */
static int            g_nroof;
/* front-end art (U6WU): MAINMENU / TITLES shape-0 bitmaps, 8-bit indexed, point into the pak. */
static const uint8_t *g_menu_pix;  static int g_menu_w, g_menu_h;
static const uint8_t *g_title_pix; static int g_title_w, g_title_h;
