static int use_object_inner(int idx)
{
    int o=g_wobj[idx].obj_n; char nm[40]; obj_name(g_wobj[idx].tile,nm,sizeof nm);
    if(instrument_effect(o)){ g_instr=instrument_effect(o); g_next_verb='I'; return 0; }
    if(o==169){ msgcat(0,"Squeak!"); sfx_play(22,0); return 1; }          /* the rubber ducky */
    if(o==334){ int fr=(int)g_wobj[idx].tile-basetile(334);              /* secret door (usecode_use.md): 0/2 hidden, 1/3 open */
        if(fr==1||fr==3) g_wobj[idx].tile--; else g_wobj[idx].tile++;
        g_msg[0]=0;
        if(g_wobj[idx].dirty!=WOBJ_DIRTY_DROPPED) g_wobj[idx].dirty=WOBJ_DIRTY_STATE; build_blocked(); return 1; }
    if(o==164||o==122||o==145||o==206||o==253){ int fr=(int)g_wobj[idx].tile-basetile(o), lit=!(fr&1);   /* fire devices: frame bit 0 = lit */
        if(o==206 && (fr&2)){ msgcat(0,"Not usable"); return 0; }
        if(lit) g_wobj[idx].tile++; else g_wobj[idx].tile--;
        if(g_wobj[idx].dirty!=WOBJ_DIRTY_DROPPED) g_wobj[idx].dirty=WOBJ_DIRTY_STATE; build_blocked();
        { int n=msgcat(0,o==122?"candle":o==145?"candelabra":o==164?"fireplace":o==206?"brazier":"campfire"); msgcat(n,lit?" is lit.":" is doused."); }
        return 1; }
    if(o==223){ int fr=(int)g_wobj[idx].tile-basetile(223);              /* powder keg: light the fuse */
        if(fr!=0){ msgcat(0,"No effect."); return 0; }
        if(g_keg_timer>0){ msgcat(0,"Not now."); return 0; }
        g_wobj[idx].tile++; if(g_wobj[idx].dirty!=WOBJ_DIRTY_DROPPED) g_wobj[idx].dirty=WOBJ_DIRTY_STATE;
        g_keg_timer=3; msgcat(0,"Powder lit!"); return 1; }
    if(o==90){ int fr=(int)g_wobj[idx].tile-basetile(90);                /* a torch on the ground: light it / burn it out */
        if(fr==0){ g_wobj[idx].tile++; if(g_wobj[idx].dirty!=WOBJ_DIRTY_DROPPED) g_wobj[idx].dirty=WOBJ_DIRTY_STATE; build_blocked(); msgcat(0,"Torch is lit."); return 1; }
        g_wobj[idx].alive=0; g_wobj[idx].dirty=WOBJ_DIRTY_DESTROYED; build_blocked(); msgcat(0,"A torch burned out."); return 1; }
    if(o>=297 && o<=300){                            /* oaken/windowed/cedar/steel door */
        int fr=(int)g_wobj[idx].tile - basetile(o);  /* 0-3 open, 4-7 closed, 8-11 locked, 12-15 magic (usecode_use.md) */
        if(fr>=12&&fr<=15){ msgcat(0,"magically locked!"); return 0; }
        if(fr>=8&&fr<=11){ msgcat(0,"locked"); return 0; }
        if(fr>=0 && fr<=3){ g_wobj[idx].tile+=4; msgcat(0,"closed!"); }
        else if(fr>=4 && fr<=7){ g_wobj[idx].tile-=4; if(trap_child(idx)>=0){ g_msg[0]=0; trap_fire(idx); } else msgcat(0,"opened!"); }
        else { msgcat(0,"Not usable"); return 0; }
        build_blocked();   /* door passability changed (closed door blocks, open doesn't) */
        return 1;
    }
    if(o==98){                                       /* a chest: 0 open, 1 closed, 2 locked, 3 magic */
        int fr=(int)g_wobj[idx].tile - basetile(o), n=0;
        if(fr==0){ g_wobj[idx].tile++; msgcat(0,"closed!"); build_blocked(); return 1; }
        if(fr!=1){ msgcat(0,"No effect"); return 0; }
        g_wobj[idx].tile--;
        if(trap_child(idx)>=0){ g_msg[0]=0; trap_fire(idx); while(g_msg[n]) n++; n=msgcat(n,"\n"); } else n=msgcat(0,"opened!\n");
        n=msgcat(n,"Searching here, you find ");
        if(!spill_container(idx,&n)) n=msgcat(n,"nothing");
        msgcat(n,".");
        build_blocked(); return 1; }
    if(o==192||o==186){                              /* a crate, a barrel: a closed one opens; either is searched */
        int fr=(int)g_wobj[idx].tile - basetile(o), n=0;
        if(fr==1){ g_wobj[idx].tile--; g_msg[0]=0; } else n=msgcat(0,"Not usable\n");
        n=msgcat(n,"Searching here, you find ");
        if(!spill_container(idx,&n)) n=msgcat(n,"nothing");
        msgcat(n,".");
        build_blocked(); return 1; }
    if(container_searchable(idx)){                   /* bag/basket/drawer/desk/body...: search directly */
        int n=msgcat(0,"Searching here, you find ");
        int found=spill_container(idx,&n); if(!found) n=msgcat(n,"nothing");
        msgcat(n,".");
        return found?1:0;
    }
    if(o==419||o==236){ ring_bell(); g_msg[0]=0; return 1; }     /* a bell, a pull chain (usecode_use.md) */
    if(o==268||o==174){                                           /* lever / switch (usecode_use.md): quality Q names the doorways of quality Q on this level;
                                                                   * at each, the barrier (portcullis / electric field) is destroyed if there, else created */
        int q=g_wobj[idx].quality, lever=(o==268), target=lever?310:175, lv=g_wp?g_wp->level:0, hit=0;
        if(!lever && q==113 && g_wobj[idx].x==139 && g_wobj[idx].y==0 && lv==1){   /* the Covetous switch: its doorway is unmarked in the data */
            int dj=obj_idx_at(160,3,301); if(dj>=0 && g_wobj[dj].quality!=113){ g_wobj[dj].quality=113; if(g_wobj[dj].dirty!=WOBJ_DIRTY_DROPPED) g_wobj[dj].dirty=WOBJ_DIRTY_STATE; } }
        if(q) for(int j=0;j<g_ow.nobjs;j++){ const wobj_t*dw=&g_wobj[j]; if(!dw->alive || dw->obj_n!=301 || dw->quality!=q) continue;
            int bj=obj_idx_at(dw->x,dw->y,target);
            if(bj<0 && lever && g_wp && (npc_at(g_wp,dw->x,dw->y)>=0 || (dw->x==g_wp->px && dw->y==g_wp->py))){ hit=2; break; }
            hit=1;
            if(bj>=0) obj_destroy(bj);
            else { int dfr=(int)dw->tile-basetile(301); int bfr=lever?((dfr&2)?3:1):0; (void)persist_obj_new(target,bfr,dw->x,dw->y,0); } }
        { int afr=(int)g_wobj[idx].tile-basetile(o); if(afr==0) g_wobj[idx].tile++; else if(afr==1) g_wobj[idx].tile--;
          if(g_wobj[idx].dirty!=WOBJ_DIRTY_DROPPED) g_wobj[idx].dirty=WOBJ_DIRTY_STATE; }
        build_blocked();
        msgcat(0, lever ? (hit==2?"Switch the lever, can't close the portcullis.":hit?"Switch the lever, you hear a noise.":"Switch the lever, strange, nothing happened.")
                        : (hit?"Operate the switch, you hear a noise.":"Operate the switch, strange, nothing happened."));
        return 1; }
    if(o==288){                                                   /* crank: the drawbridge (usecode_use.md) */
        /* DOS takes the first piece with the crank's quality among the objects it holds: the 2x2 superchunks
         * round the party on the surface. Seen in DOS: that piece is the bridge's start, the closed row's
         * left end (frame 6) or the top open row's left end (frame 3); any other frame: nothing happens */
        int M=U6_SURFACE_TILES-1, sx=-1, sy=-1, q=g_wobj[idx].quality, lv=g_wp?g_wp->level:0, any_q=0, best=-1;
        int wx=0, wy=0, wn=U6_SURFACE_TILES;
        if(g_wp && lv==0){ wx=(g_wp->px-64)>>7; wy=(g_wp->py-64)>>7; if(wx<0) wx=0; if(wy<0) wy=0; if(wx>6) wx=6; if(wy>6) wy=6; wx<<=7; wy<<=7; wn=256; }
        for(int j=0;j<g_ow.nobjs;j++){ const wobj_t*b=&g_wobj[j]; if(!b->alive || b->obj_n!=269 || b->quality!=q) continue;
            if(b->x<wx || b->x>=wx+wn || b->y<wy || b->y>=wy+wn) continue;
            any_q=1; { int f=(int)b->tile-basetile(269); if(f!=3 && f!=6) continue; }
            if(best<0 || b->y<g_wobj[best].y || (b->y==g_wobj[best].y && b->x<g_wobj[best].x)) best=j; }
        if(!any_q){ msgcat(0,"No correspondent drawbridge"); return 0; }
        if(best<0){ msgcat(0,"Strange, nothing happened."); return 0; }
        sx=g_wobj[best].x; sy=g_wobj[best].y;
        if((int)g_wobj[best].tile-basetile(269)==6) sx=(sx+1)&M;    /* closed: the open rows start one tile right */
        int si=obj_idx_at(sx,sy,269), open=(si>=0 && (int)g_wobj[si].tile-basetile(269)==3);
        if(g_wp){ int span=0, rows=16; while(span<32 && obj_idx_at((sx+span)&M,sy,269)>=0) span++;   /* anything on the deck stops it */
            for(int h=open?0:1;h<rows;h++){ int any=0; for(int i=0;i<span;i++){ int bx=(sx+i)&M, by=(sy+h)&M; if(open&&obj_idx_at(bx,by,269)<0) continue; any=1;
                    { int ob=objworld_at(&g_ow,bx,by); if(npc_at(g_wp,bx,by)>=0 || (bx==g_wp->px&&by==g_wp->py) || (ob>=0&&g_wobj[ob].obj_n!=269)){ msgcat(0,open?"Can't close the drawbridge.":"Can't open the drawbridge."); return 0; } } }
                if(open&&!any) break; if(!open && bridge_end_tile(g_wp,(sx+1)&M,(sy+h+1)&M)) break; } }
        { int e=obj_idx_at((sx-1)&M,sy,269); if(e>=0) obj_destroy(e); }   /* the closed row's end piece */
        int W=0;
        for(int h=0;h<32;h++){ int wd=0; for(;wd<32;wd++){ int pi=obj_idx_at((sx+wd)&M,(sy+h)&M,269); if(pi<0) break; obj_destroy(pi); }
            if(wd==0) break; if(h==0) W=wd; }
        if(W<2) W=2;
        if(open){                                                 /* close: one raised row above the start */
            (void)persist_obj_new(269,6,(sx-1)&M,(sy-1)&M,0); (void)persist_obj_new(269,8,(sx+W-1)&M,(sy-1)&M,0);
            for(int i=0;i<W-1;i++) (void)persist_obj_new(269,7,(sx+i)&M,(sy-1)&M,0);
            msgcat(0,"Close the drawbridge.");
        } else {                                                  /* open: chained rows down to passable ground, then the far end */
            int yy=(sy+1)&M, i;
            for(i=0;i<16;i++){ (void)persist_obj_new(269,3,sx,(yy+i)&M,0); (void)persist_obj_new(269,5,(sx+W-1)&M,(yy+i)&M,0);
                for(int j=0;j<W-2;j++) (void)persist_obj_new(269,4,(sx+1+j)&M,(yy+i)&M,0);
                if(g_wp && bridge_end_tile(g_wp,(sx+1)&M,(yy+i+1)&M)) break; }
            i++;
            for(int j=0;j<W-2;j++) (void)persist_obj_new(269,1,(sx+1+j)&M,(yy+i)&M,0);
            (void)persist_obj_new(269,0,sx,(yy+i)&M,0); (void)persist_obj_new(269,2,(sx+W-1)&M,(yy+i)&M,0);
            msgcat(0,"Open the drawbridge.");
        }
        if(g_wobj[idx].dirty!=WOBJ_DIRTY_DROPPED) g_wobj[idx].dirty=WOBJ_DIRTY_STATE;
        build_blocked(); return 1; }
    { int fk=is_food_objn(o);                                     /* eat / drink (usecode_use.md Food): consume one, no hunger model */
      if(fk){ msgcat(0, fk==2?"You drink it.":"You eat the food.");
          if(fk==2 && g_alcohol<255) g_alcohol++;
          if(g_wobj[idx].qty>1){ g_wobj[idx].qty--;                /* the record's count follows at once */
              int32_t c; int k; if(!is_temp_obj(idx) && g_wobj[idx].dirty!=WOBJ_DIRTY_NEW && rec_locate(idx,&c,&k,0)){ uint8_t*r=g_savetmpl+c+2+k*8; int q=(int)g_wobj[idx].qty;
                  if(is_stackable(o)){ r[6]=(uint8_t)(q&0xff); r[7]=(uint8_t)(q>>8); } else r[6]=(uint8_t)q; } }
          else obj_destroy(idx);
          return 1; } }
    if(use_common((world_t*)g_wp,o,g_wobj[idx].x,g_wobj[idx].y,idx)>=0) return 1;
    if(o==212||o==264||o==93||(o>=242&&o<=249)||o==87||o==62||o==78||o==103||o==104||o==420||o==77||o==275||o==73){   /* these work where they lie too */
        g_use_idx=idx; int pr=use_pack_item((world_t*)g_wp,o); g_use_idx=-1;
        if(!g_next_verb) g_next_verb=pr==2?'O':pr==3?'P':pr==4?'C':0;
        return pr==1; }
    msgcat(0,"Not usable");
    return 0;
}

/* --- Savage Empire USE (docs/formats/se_md_objn.md) ------------------------------------------
 * SE's obj_n differ from U6's, so USE gets its own handler behind the g_gd seam. V1 covers the two
 * GENERIC, verifiable actions (reusing the shared, U6-proven mechanisms), keyed on the surveyed SE
 * obj_n: SEARCH a container (spill its children onto the map) and EAT food. DOORS are deferred: SE
 * door frames are per-object and share tile ranges with other objects (survey via
 * `objsurvey ... frames`), so there is no clean open/close delta — they need a per-object frame table. */
/* the bot's doors: U6's door types by frame (usecode_use.md Doors) */
static int u6_bot_door(const wobj_t*o){ return (g_on.door_n&&o->obj_n>=g_on.door_first&&o->obj_n<g_on.door_first+g_on.door_n)?(int)o->tile-basetile(o->obj_n):-1; }
/* ---- Savage Empire U)se (docs/rules/se_use.md) ---- */
static const uint16_t SE_USABLE[]={6,10,20,22,25,29,42,43,44,47,49,50,51,52,59,60,61,62,63,79,80,81,82,86,87,88,92,93,94,
    95,102,103,104,105,106,107,108,109,110,111,113,114,119,120,131,134,136,137,143,148,161,165,173,177,186,188,190,191,192,
    197,204,207,208,209,212,213,214,216,217,221,229,233,234,237,240,242,247,252,254,257,275,302,307};   /* §2 */
static int se_usable(int on){ for(unsigned k=0;k<sizeof SE_USABLE/sizeof SE_USABLE[0];k++) if(SE_USABLE[k]==on) return 1; return 0; }
static int se_is_food(int on){ return on==93||(on>=102&&on<=111)||on==113||on==114||on==120||on==197||on==213||on==214; }   /* the food case (§3) */
static int se_frame(int idx){ return (int)g_wobj[idx].tile-basetile(g_wobj[idx].obj_n); }
/* an actor within the view: 5 tiles across and 4 down of its centre (0xa5d:0x613) */
static int se_on_screen(int id){ int x,y; if(!g_wp||!actor_pos(id,&x,&y)) return 0;
    int dx=x-(int)g_wp->px, dy=y-(int)g_wp->py; return dx>=-5&&dx<=5&&dy>=-4&&dy<=4; }
/* join the party as SE does (0xf8d:0x290): five members besides Aiela, Yunapotli and Johann */
static void se_join(int id)
{
    int room=5; if(is_party_member(id)) return;
    for(int j=0;j<g_nparty;j++){ int a=g_party[j].actor; if(a!=2&&a!=11&&a!=5) room--; }
    if((room<1 && id!=2&&id!=11&&id!=5) || g_nparty>=MAXPARTY) return;
    g_party[g_nparty].actor=id; g_party[g_nparty].hp=g_ahp[id]?g_ahp[id]:30;
    { int32_t got=se_script(id); int o=0;                       /* the name heads the script: 0xFF, the actor, the name, 0xF1 */
      for(int32_t i=2;i<got&&g_script_buf[i]!=0xf1&&g_script_buf[i]>=0x20&&g_script_buf[i]<0x80&&o<15;i++) g_party[g_nparty].name[o++]=(char)g_script_buf[i];
      g_party[g_nparty].name[o]=0; }
    g_nparty++; g_away[id]=0;
    if(g_savetmpl && g_objlist_off>=0){ pool_absorb(g_savetmpl, g_savetmpl_len, g_objlist_off, id); equip_refold(id); }
}
/* a door slides onto a tile only if nothing solid lies there (§4) */
static int se_door_blocked(int x,int y,int self)
{   for(int j=0;j<g_ow.nobjs;j++){ const wobj_t*o=&g_wobj[j];
        if(j==self||!o->alive||o->parent!=WOBJ_PARENT_NONE||o->x!=(uint16_t)x||o->y!=(uint16_t)y) continue;
        if(o->obj_n==234||o->obj_n==236||o->obj_n==226) continue;
        if(!(g_tflags3 && (g_tflags3[o->tile]&0x10))) return 1; }
    return 0; }
static void se_door_move(int idx,int x,int y,int fr)
{   wobj_t*o=&g_wobj[idx]; o->x=(uint16_t)x; o->y=(uint16_t)y; o->tile=(uint16_t)(basetile(o->obj_n)+fr);
    if(!o->dirty) o->dirty=WOBJ_DIRTY_STATE; build_blocked(); }
static void se_door_vanish(int idx){ g_wobj[idx].alive=0; g_wobj[idx].dirty=WOBJ_DIRTY_DESTROYED; build_blocked(); }
static int se_use_door(int idx)
{
    int on=g_wobj[idx].obj_n, fr=se_frame(idx), x=g_wobj[idx].x, y=g_wobj[idx].y;
    if(on==234){                                            /* the door: shut at 5/7 across its doorway, open at 1/3 (§4) */
        if(fr==1||fr==3){ int nx=x+(fr==1), ny=y+(fr==3);   /* shut it, unless something is in the way */
            if(se_door_blocked(nx,ny,idx)){ msgcat(0,"\nThe door is blocked."); return 0; }
            se_door_move(idx,nx,ny,fr+4); return 1; }
        if(fr==5){ se_door_move(idx,x-1,y,1);                /* open it */
            if(x==388&&y==565&&g_cur_level==0&&!(g_cg.talk_flags[4]&0x10)&&se_on_screen(4)){   /* Jimmy's door: his talk flag 4, once */
                g_asleep[4]=0; g_cg.talk_flags[4]|=0x10; se_join(4); se_talk_open(4); }
            return 1; }
        if(fr==7){ se_door_move(idx,x,y-1,3); return 1; }
        return 0; }
    if(on==161){                                            /* Yunapotli's door */
        if(is_party_member(11) && se_on_screen(11)){   /* status 0x80: in the party */
            msgcat(0,"\nYunapotli closes its eyes and appears to concentrate.  There is a grinding noise froom the direction of the doors...  and they slide open!");
            se_door_vanish(idx); return 1; }
        msgcat(0,"You can't budge it!"); return 0; }
    if(on==275){                                            /* the swinging door; Aiela's scene waits for item 9 */
        if(fr==1){ g_wobj[idx].tile=(uint16_t)(basetile(on)+3); build_blocked(); return 1; }
        if(fr==3){ g_wobj[idx].tile=(uint16_t)(basetile(on)+1); build_blocked(); return 1; }
        return 0; }
    return 0;
}
/* SE's doors for the bot: 234 shut at 5/7 (open, it has left the doorway: the map says the rest); 275 shut at 1,
 * open at 3; Yunapotli's never opens to the bot */
static int se_bot_door(const wobj_t*o){ int fr=(int)o->tile-basetile(o->obj_n);
    if(o->obj_n==234) return (fr==5||fr==7)?fr:-1; if(o->obj_n==275) return fr==1?5:fr==3?1:fr; if(o->obj_n==161) return 8; return -1; }
static int use_actor(void); static int carry_over(int a,int extra);
#define SEON_FIRE 1                                         /* the fire, the oven, the fire pit, lava (0x2215f) */
#define SEON_KNIFE 2                                        /* a knife or the scissors (0x22488) */
