        if(on==108) corn=kid[k]; else if(on==129) ing[0]=kid[k]; else if(on==123) ing[1]=kid[k]; else if(on==130) ing[2]=kid[k];
        else { msgcat(0,"\nYou can't grind that!"); return 0; }
