/* the digging stick (0x21f60, se_use.md §5p): clay from the first clay tile around its holder */
static int se_dig(int a){
    int x,y; se_actor_xy(a,&x,&y);
    for(int dx=-1;dx<=1;dx++) for(int dy=-1;dy<=1;dy++){ int t; if(!dx&&!dy) continue;
        t=world_tile(g_wp,x+dx,y+dy)&0xff; if(!((t>=0x20&&t<=0x2f)||t==0xbe)) continue;
        msgcat(0,"\nYou get some clay."); if(!se_give(a,192,1)) se_drop_new(192,1,x+dx,y+dy); return 1; }
    msgcat(0,"\nThere is nothing to dig!"); return 1; }
/* the machine (0x25b44, se_use.md §5r): a gem from the leader's pack, and a fruit comes out on the machine's tile */
static int se_machine(int idx){
    int lead=g_nparty?g_party[0].actor:1, k;
    for(k=0;k<g_ow.ninv;k++){ int on=g_ow.inv[k].obj_n; if((g_ow.inv[k].owner?g_ow.inv[k].owner:1)==lead && !g_ow.inv[k].in && (on==72||on==73||on==74)) break; }
    if(k>=g_ow.ninv){ msgcat(0,"\nYou don't have any gems."); return 1; }
    pack_row_take(k,1); msgcat(0,"\nYou put a gem in the machine.");
    persist_obj_new(197,0,g_wobj[idx].x,g_wobj[idx].y,0); build_blocked(); return 1; }
/* the wire screen (0x23b10, se_use.md §5r): ten sulfur from the first sulfur deposit (231) around its holder */
static int se_sift(int a){
    int x,y; se_actor_xy(a,&x,&y);
    for(int dx=-1;dx<=1;dx++) for(int dy=-1;dy<=1;dy++){ if(!dx&&!dy) continue;
        if(obj_idx_at(x+dx,y+dy,231)<0) continue;
        msgcat(0,"\nYou made some sulphur powder."); if(!se_give(a,123,10)) se_drop_new(123,10,x,y); return 1; }
    msgcat(0,"\nThere is nothing to sift."); return 1; }
/* the metal head (0x24147, se_use.md §5s): on the headless statue (247) beside its holder, the statue is actor 11, who joins */
static int se_head(int idx,int row,int a){
    int x,y; se_actor_xy(a,&x,&y);
    for(int dx=-1;dx<=1;dx++) for(int dy=-1;dy<=1;dy++){ int st; if(!dx&&!dy) continue;
        st=obj_idx_at(x+dx,y+dy,247); if(st<0||!g_wobj[st].alive) continue;
        se_use_up(idx,row,1); obj_destroy(st); build_blocked();
        g_actx[11]=(uint16_t)x; g_acty[11]=(uint16_t)y; g_actz[11]=(uint8_t)g_cur_level;   /* where the holder stands, as DOS puts it */
        se_join(11); g_cg.talk_flags[11]|=0x40;
        msgcat(0,"\nYou replace the statue's missing head."); return 1; }
    msgcat(0,"\nNo effect."); return 0; }
/* clay (0x2204a, se_use.md §5t): a soft pot from one clay */
static int se_clay(int idx,int row,int a){
    int x,y; if(idx>=0){ x=g_wobj[idx].x; y=g_wobj[idx].y; } else se_actor_xy(a,&x,&y);
    se_use_up(idx,row,0);
    if(!(row>=0 && se_give(a,132,1))) se_drop_new(132,1,x,y);
    msgcat(0,"\nYou shaped a small, soft pot from the clay."); return 1; }
/* the fishing pole (0x21b48, se_use.md §5u): deep water (map tile 0x0c) on the diagonal through the holder, as DOS looks */
static int se_fish(int a){
    int x,y; se_actor_xy(a,&x,&y);
    for(int i=0;i<3;i++) for(int j=0;j<3;j++){ if(i==1&&j==1) continue;
        if((world_tile(g_wp,x+i-1,y+j-1)&0xff)!=0x0c) continue;                 /* all eight (DOS looks along a diagonal, se_deviations.md 4) */
        if(se_rand(0,4)==0 && se_give(a,213,1)) msgcat(0,"\nYou caught a fish!"); else msgcat(0,"\nYou didn't get a fish.");
        return 1; }
    msgcat(0,"\nYou need to stand next to deep water."); return 1; }
/* the crystal garden (0x25d54, se_use.md §5u): Rafkin (7), else Johann (5), in the party, alive, awake and on screen, finds
 * potassium nitrate: 10 to the leader */
static int se_crystals(void){
    int who=-1, lead=g_nparty?g_party[0].actor:1;
    static const uint8_t W[2]={7,5};
    for(int k=0;k<2&&who<0;k++){ int id=W[k]; if(is_party_member(id) && !g_adead[id] && !g_asleep[id] && se_on_screen(id)) who=id; }
    if(who<0){ msgcat(0,"\nThere is nobody in the party who can identify which crystals are useful."); return 1; }
    if(!se_give(lead,130,10)){ msgcat(0,"\nYou are carrying too much already."); return 1; }
    msgcat(0,who==7?"\nRafkin identifies some potassium nitrate, and you scrape a quantity from the crystal.":"\nJohann identifies some potassium nitrate, and you scrape a quantity from the crystal.");
    return 1; }
/* the headless metal statue (0x2423a, se_use.md §5s): with the metal head in the leader's pack, the statue (actor 11) joins */
static int se_statue(int idx){
    int lead=g_nparty?g_party[0].actor:1, k, x=g_wobj[idx].x, y=g_wobj[idx].y;
    for(k=0;k<g_ow.ninv;k++) if(g_ow.inv[k].obj_n==190 && (g_ow.inv[k].owner?g_ow.inv[k].owner:1)==lead) break;
    if(k>=g_ow.ninv){ msgcat(0,"\nNo effect."); return 0; }
    pack_row_take(k,1); obj_destroy(idx); build_blocked();
    g_actx[11]=(uint16_t)x; g_acty[11]=(uint16_t)y; g_actz[11]=(uint8_t)g_cur_level;   /* where the statue stood */
    se_join(11); g_cg.talk_flags[11]|=0x40;
    msgcat(0,"\nYou replace the statue's missing head."); return 1; }
static int se_bait(world_t*w,int idx,int row);   /* the turtle bait (defined with the vehicles) */
static int se_totem(int on,int has_acting);
static int se_use_object(int idx)
{
    int o=g_wobj[idx].obj_n; char nm[40]; obj_name(g_wobj[idx].tile,nm,sizeof nm);
    if(o>=86&&o<=88) return se_totem(o,0);
    if(o==43){ g_se_on=SEON_BELL; g_se_on_actor=use_actor(); g_se_on_idx=idx; g_se_on_row=-1; g_next_verb='X'; return 0; }   /* the bell asks "On " (se_use.md §5i) */                         /* a totem on the ground: only a leading Triolo (se_use.md §5n) */
    if(o==234||o==161||o==275) return se_use_door(idx);
    if(o==173||o==242||o==254||o==257){ g_se_on=SEON_FIRE; g_next_verb='X'; return 0; }   /* the oven and the fires ask "On " */
    if(o==188){                                      /* the crate: a shut one (frame 1) opens, else "Not possible."; then the search (0x1ec8a) */
        int fr=se_frame(idx), n=0;
        if(fr==1){ g_wobj[idx].tile=(uint16_t)basetile(188); if(!g_wobj[idx].dirty) g_wobj[idx].dirty=WOBJ_DIRTY_STATE; }
        else n=msgcat(0,"\nNot possible.");
        if(se_frame(idx)!=0) return 0;               /* the search takes only an open crate */
        n=msgcat(n,"\nSearching here, you find ");
        int found=spill_container(idx,&n); if(!found) n=msgcat(n,"nothing");
        msgcat(n,".");
        return 1;
    }
    if(o==186){ if(se_frame(idx)&2){ msgcat(0,"\nNot possible."); return 0; } g_se_on=SEON_FIRE; g_next_verb='X'; return 0; }   /* the brazier: lit, a fire */
    if(o==207){ int fr=se_frame(idx);                /* burnt logs: 0 not possible, 1 lit, 2 burning (a fire) */
        if(fr==0){ msgcat(0,"\nNot possible."); return 0; }
        if(fr==1){ g_wobj[idx].tile=(uint16_t)(basetile(207)+2); if(!g_wobj[idx].dirty) g_wobj[idx].dirty=WOBJ_DIRTY_STATE; msgcat(0,"\nYou started a fire."); return 1; }
        if(fr==2){ g_se_on=SEON_FIRE; g_next_verb='X'; return 0; }
        return 1; }
    if(o==137||o==240) return se_light(idx,-1,0,0);
    if(o==6) return se_gem(idx,-1,use_actor());
    if(o==10) return se_ribbon(idx,-1,use_actor());
    if(o==49) return se_notebook();
    if(o==59||o==60) return se_grind(idx,-1);
    if(o==92) return se_unfold(idx);
    if(o==131) return se_dig(use_actor());
    if(o==47) return g_wp?se_bait((world_t*)g_wp,idx,-1):0;
    if(o==95){ se_use_up(idx,-1,1); if(g_alcohol<255) g_alcohol++; msgcat(0,"\nYou drink it."); return 1; }   /* the bottle of liquor (0x21c2d) */
    if(o>=79&&o<=82){ if(!se_give(use_actor(),211,1)){ msgcat(0,"\nYou are carrying too much already."); return 0; }   /* bones, the skeleton (0x23f4b) */
        msgcat(0,"\nYou got some rib bones."); return 1; }
    if(o==61||o==62){ if(!se_give(use_actor(),o==61?108:109,1)){ msgcat(0,"\nYou are carrying too much already."); return 0; }   /* the stalks (0x23ea5, 0x23e52) */
        msgcat(0,o==61?"\nYou got some corn from the plant.":"\nYou got some beans from the plant."); return 1; }
    if(o==51) return se_camera(idx,-1,use_actor());
    if(o==50) return se_flintlock(idx,-1,use_actor());
    if(o==25||o==44||o==52){ g_se_on=SEON_KNIFE; g_se_on_actor=use_actor(); g_next_verb='X'; return 0; }   /* knives and scissors ask "On " */
    if(o==29||o==119){ g_se_on=SEON_HAMMER; g_se_on_actor=use_actor(); g_next_verb='X'; return 0; }   /* the hammers too */
    if(o==136) return se_bucket(idx,-1);
    if(o==143) return se_machine(idx);
    if(o==190) return se_head(idx,-1,use_actor());
    if(o==192) return se_clay(idx,-1,use_actor());
    if(o==208) return se_torch(idx,-1,use_actor());
    if(o==212) return se_fish(use_actor());
    if(o==216) return se_crystals();
    if(o==247) return se_statue(idx);
    if(o==252){ g_se_on=SEON_CRYSTAL; g_se_on_actor=use_actor(); g_se_on_idx=idx; g_se_on_row=-1; g_next_verb='X'; return 0; }
    if(o==229){ g_se_on=SEON_TARPIT; g_se_on_actor=(g_show_inv&&g_status_actor>=1)?g_status_actor:(g_nparty?g_party[0].actor:1); g_next_verb='X'; return 0; }   /* the member shown, else the leader */
    if(o==209){ g_se_on=SEON_LTORCH; g_se_on_actor=use_actor(); g_next_verb='X'; return 0; }
    if(o==204){ g_se_on=SEON_POWDER; g_se_on_actor=use_actor(); g_se_on_idx=idx; g_se_on_row=-1; g_next_verb='X'; return 0; }
    if(o==191){ g_se_on=SEON_TARSTRIP; g_se_on_actor=use_actor(); g_se_on_idx=idx; g_se_on_row=-1; g_next_verb='X'; return 0; }
    if(o==177) return se_sift(use_actor());
    if(o==165){ g_se_on=SEON_LOOM; g_se_on_actor=g_nparty?g_party[0].actor:1; g_next_verb='X'; return 0; }   /* the loom: the leader's On */
    if(o==134){ g_se_on=SEON_STRIPS; g_se_on_actor=use_actor(); g_se_on_idx=idx; g_se_on_row=-1; g_next_verb='X'; return 0; }
    if(o==94){ g_se_on=SEON_EXTING; g_se_on_actor=use_actor(); g_next_verb='X'; return 0; }
    if(o==63){ g_se_on=SEON_PLACHTA; g_se_on_actor=use_actor(); g_se_on_idx=idx; g_se_on_row=-1; g_next_verb='X'; return 0; }
    if(o==42){ g_se_on=SEON_VINE; g_se_on_actor=use_actor(); g_se_on_idx=idx; g_se_on_row=-1; g_next_verb='X'; return 0; }
    if(se_is_food(o)){                               /* eat (0x21df5): no more than that */
        msgcat(0,"\nYou eat the food."); se_use_up(idx,-1,0); return 1;
    }
    int n=msgcat(0,"Nothing happens with the "); n=msgcat(n,nm); msgcat(n,".");   /* the cases not yet read (§3) */
    return 0;
}

/* U)se a thing in the pack or readied (the same switch, 0x25e46): the row is the one chosen */
static int g_use_slot=-1;                                   /* the readied slot being used (panel_select_slot), or -1 */
/* ---- the totems' invocations (0x12ef7; docs/rules/se_invoke.md) ---- */
static int align_of(int i); static int wt_now(int i); static int member(int i); static void charm_end(int id);
static int se_hatch_creature(const world_t*w,int x,int y,int on);
static void se_big_hatch(const world_t*w,int i); static void se_big_drop(int i); static void se_lie(int i); static int se_sleep_body(int i); static int se_wide_frame(int bt,int tile,int f);
static int g_se_offer;                                        /* the invocation asked: totem << 4 (Heluzz 0, Aphazz 0x10, Motazz 0x20) */
/* the actors in the 11 x 9 around the leader (0x126e4) */
static int se_invoke_near(int*out,int cap)
{   int n=0, M=((g_wp&&g_wp->level==0)?U6_SURFACE_TILES:256)-1;
    for(int dx=0;dx<11;dx++) for(int dy=0;dy<9;dy++){ int x=((int)g_wp->px+dx-5)&M, y=((int)g_wp->py+dy-4)&M;
        for(int a=1;a<U6_MAX_ACTORS&&n<cap;a++){ int ax,ay; if(g_atile[a]==0xffff||!actor_where(a,&ax,&ay)||ax!=x||ay!=y) continue; out[n++]=a; } }
    return n; }
/* an invocation's power against one (0x1862a): intelligence, 3 less cursed or wild (but the leader), at least 1 */
static int se_power(int a){ int v=g_aint[a]; if(g_curse[a]||(g_se_wild[a]&&a!=1)) v-=3; return v<1?1:v; }
/* 1 = it shrugs the invocation off (0x18662): a drone 1 in 10, the queen never, else its power over Triolo's beyond -12..12 (slip 21) */
static int se_resists(int t)
{   int on=actor_objn(t);
    if(on==323) return se_rand(1,10)==1;
    if(on==328) return 0;
    { int c=9; if(g_dos_slips){ c=member_index(g_status_actor>=1?g_status_actor:1); if(c<0) c=0; }   /* DOS reads the shown member's party slot as an actor */
      return se_power(t)-se_power(c)>se_rand(-12,12); } }
/* "A, B and C are healed." / "X is healed." (0x129f8) */
static void se_invoke_list(const int*l,int n,const char*state)
{   char nm[32]; int m=msg_tail();
    if(!n){ msgcat(m,"No effect.\n"); return; }
    m=msgcat(m,"\n");
    for(int k=0;k<n-2;k++){ actor_name(l[k],nm,sizeof nm); m=msgcat(m,nm); m=msgcat(m,", "); }
    if(n>1){ actor_name(l[n-2],nm,sizeof nm); m=msgcat(m,nm); m=msgcat(m," and "); actor_name(l[n-1],nm,sizeof nm); m=msgcat(m,nm); m=msgcat(m," are "); }
    else { actor_name(l[0],nm,sizeof nm); m=msgcat(m,nm); m=msgcat(m," is "); }
    m=msgcat(m,state); msgcat(m,"\n"); }
/* Heluzz and yopo: Triolo senses danger (0x127ab) */
static void se_sense(void)
{   static const char*const D[8]={"north","northeast","east","southeast","south","southwest","west","northwest"};
    int cnt[8]={0}, k, nd=0, m;
    for(int a=16;a<U6_MAX_ACTORS;a++){ int ax,ay,dx,dy; if(g_atile[a]==0xffff||!g_ahp[a]||(int)g_actz[a]!=g_wp->level||!actor_where(a,&ax,&ay)) continue;
        if(!(align_of(a)&0x20) && wt_now(a)!=0x9b) continue;
        dx=ax-(int)g_wp->px; dy=ay-(int)g_wp->py; if(iabs_(dx)>25||iabs_(dy)>25) continue;
        if(!dy) dy=-1; if(!dx) dx=-1;
        if(iabs_(dx)<iabs_(dy)/2) cnt[dy>0?4:0]++;
        else if(iabs_(dy)<iabs_(dx)/2) cnt[dx>0?2:6]++;
        else cnt[dx>0?(dy>0?3:1):(dy>0?5:7)]++; }
    for(k=0;k<8;k++) if(cnt[k]) nd++;
    m=msgcat(msg_tail(),"\nTriolo senses ");
    if(!nd){ msgcat(m,"no danger.\n"); return; }
    if(nd==8){ msgcat(m,"danger all around!\n"); return; }
    m=msgcat(m,"danger to the ");
    for(int left=nd;left>0;left--){ for(k=0;k<8&&!cnt[k];k++); m=msgcat(m,D[k]); cnt[k]=0;
        if(left>2) m=msgcat(m,", "); else if(left==2) m=msgcat(m," and "); }
    msgcat(m,".\n"); }
/* Motazz and chocolatl: a beast comes to fight beside the party, on the surface, one at a time (0x1259e) */
static void se_helper(world_t*w)
{   int on=(g_veh_kind?300:331), s, M=U6_SURFACE_TILES-1;          /* a plesiosaur for one on the water, else a sabretooth tiger */
    if(!g_se_helper && (s=se_hatch_creature(w,(int)w->px,(int)w->py,on))>=0){
        for(int t=0;t<8;t++){ int x=((int)w->px+se_rand(0,10)-5)&M, y=((int)w->py+se_rand(0,10)-5)&M, ok;
            g_mover=s; ok=mover_can_enter(w,x,y)&&!npc_occupied(s,x,y)&&!(x==(int)w->px&&y==(int)w->py); g_mover=-1;
            if(!ok) continue;
            g_actx[s]=(uint16_t)x; g_acty[s]=(uint16_t)y; g_temp[s]=0;
            g_agood[s]=1; g_achaos[s]=0; g_align_hostile[s]=0; g_alert[s]=0; g_ally[s]=1; hatched_worktype(s,8);
            g_se_helper=s; build_blocked(); msgcat(msg_tail(),"Success!\n"); return; }
        g_atile[s]=0xffff; g_temp[s]=0; }
    msgcat(msg_tail(),"Failed.\n"); }
/* the invocation, its offering made (0x12d86 and 0x129f8) */
static void se_invoke_do(world_t*w,int k)
{   int l[64], near[128], nn=se_invoke_near(near,128), n=0;
    switch(k){
    case 0x00: g_peer_on=1; msgcat(msg_tail(),"\nTriolo leaves his body and looks down at the party!\n"); return;
    case 0x01: g_spell_light_turns=200; g_spell_light_rad=4; msgcat(msg_tail(),"\nTriolo creates light.\n"); return;
    case 0x02: se_sense(); return;
    case 0x21: if(w->level){ msgcat(msg_tail(),"\nNo help available.\n"); return; } se_helper(w); return; }
    for(int j=0;j<nn&&n<64;j++){ int a=near[j], in=member(a);
        switch(k){
        case 0x10: if(in && g_ahp[a] && (g_ahp[a]<se_max_hp(a)||g_poison[a])){ int h=g_ahp[a]+se_rand(1,10), mx=se_max_hp(a); g_ahp[a]=(uint8_t)(h>mx?mx:h); g_poison[a]=0; l[n++]=a; } break;
        case 0x11: if((align_of(a)&0x20) && !g_charm[a] && !se_resists(a)){ g_charm_sv[a]=(uint8_t)((g_hostile[a]?1:0)|(g_align_hostile[a]?2:0)|(g_alert[a]?4:0));
                g_wt_keep[a]=g_wt_force[a]; g_wt_force[a]=8; g_charm[a]=255; g_ally[a]=1; g_hostile[a]=0; g_alert[a]=0; l[n++]=a; } break;
        case 0x12: if(in && !g_se_prot[a]){ g_se_prot[a]=1; l[n++]=a; } break;
        case 0x20: if((align_of(a)&0x20) && !g_curse[a] && !se_resists(a)){ g_curse[a]=255; l[n++]=a; } break;
        case 0x22: if(in && !g_se_wild[a]){ g_se_wild[a]=1; if(a!=1) l[n++]=a; } break; } }
    if(k==0x12){ msgcat(msg_tail(),"\nAphazz protects the party.\n"); return; }
    se_invoke_list(l,n,k==0x10?"healed.":k==0x11?"charmed.":k==0x20?"cursed!":"wild!");
    sync_party_hp(); }
/* the offering answered (0x12ef7): chocolatl, pinde or yopo, within a tile of the leader */
static int se_offer_on(int idx,int row)
{   int k=g_se_offer, n=msgcat(msg_end(),"offering-- "), on;
    g_se_on=0; g_verb_pts=5;
    if(idx<0&&row<0){ msgcat(n,"nothing!\n"); return 0; }
    on=idx>=0?g_wobj[idx].obj_n:g_ow.inv[row].obj_n;
    n=look_thing(n,on,idx>=0?g_wobj[idx].tile:g_ow.inv[row].tile,1,0); n=msgcat(n,"\n");
    if(idx>=0){ int ax,ay; se_leader_pos(&ax,&ay); if(iabs_((int)g_wobj[idx].x-ax)>1||iabs_((int)g_wobj[idx].y-ay)>1){ msgcat(n,"Out of range!\n"); return 0; } }
    if(on==54) k|=1; else if(on==56) k|=2; else if(on!=55){ msgcat(n,"\nOffering refused.\n"); return 0; }
    se_invoke_do((world_t*)g_wp,k);
    if(row>=0) pack_row_take(row,1);
    else if(g_wobj[idx].qty>1){ g_wobj[idx].qty--; if(!g_wobj[idx].dirty) g_wobj[idx].dirty=WOBJ_DIRTY_STATE; }
    else { obj_destroy(idx); build_blocked(); }
    return 1; }
/* a totem used (the use switch, se_use.md §5n): Triolo's, or the leader's when Triolo leads */
static int se_totem(int on,int has_acting)
{   int acting=use_actor(), leader=g_nparty?g_party[0].actor:1, n;
    if(g_show_inv&&g_status_actor>=1) acting=g_status_actor;
    if(!((has_acting&&acting==9)||(!has_acting&&leader==9))){ char nm[32]; actor_name(acting,nm,sizeof nm); n=msgcat(msg_tail(),"\n"); n=msgcat(n,nm); msgcat(n," can't use that!\n"); return 0; }
    n=msgcat(msg_tail(),"\nInvoke: ");
    if(on==86){ msgcat(n,"Heluzz!\n"); g_se_offer=0; }
    else if(on==88){ msgcat(n,"Aphazz!\n"); g_se_offer=0x10; }
    else if(!g_combat_mode){ msgcat(n,"Motazz aids only those who are in mortal combat.\n"); return 0; }
    else { msgcat(n,"Motazz!\n"); g_se_offer=0x20; }
    g_se_on=SEON_OFFER; g_next_verb='X'; return 0; }
/* SE's wear-offs as time passes (0x359:0x11b6): protection, curses and charms 1 in 25, the frenzy and Motazz's beast with combat */
static void se_status_tick(void)
{   for(int a=1;a<U6_MAX_ACTORS;a++){ if(a!=1&&g_atile[a]==0xffff) continue;
        if(a==g_se_helper && !g_combat_mode){ g_wt_force[a]=0x13; g_agood[a]=0; g_achaos[a]=1; g_align_hostile[a]=1; g_ally[a]=0; g_temp[a]=1; g_se_helper=0; }
        if(g_se_prot[a] && !se_rand(0,24)) g_se_prot[a]=0;
        if(g_se_wild[a] && !g_combat_mode) g_se_wild[a]=0;
        if(g_curse[a] && !se_rand(0,24)) g_curse[a]=0;
        if(g_charm[a] && !se_rand(0,24)) charm_end(a);
        se_lie(a); }
    if(g_se_helper && (g_se_helper>=U6_MAX_ACTORS||g_atile[g_se_helper]==0xffff)) g_se_helper=0; }
static int se_use_pack(world_t*w,int on)
{
    int row=-1, a=g_status_actor>=1?g_status_actor:1; (void)w;
    if(!g_use_readied){ if(g_inv_sel>=0 && g_inv_sel<g_ow.ninv && g_ow.inv[g_inv_sel].obj_n==on) row=g_inv_sel;
        else for(int k=0;k<g_ow.ninv && row<0;k++) if(g_ow.inv[k].obj_n==on) row=k;
        if(row<0) return 0; }
    else if(g_use_slot<0 || g_aready[a][g_use_slot]!=on) return 0;
    if(!se_usable(on)){ msgcat(0,"\nNot possible."); return 0; }
    g_verb_pts=5;
    if(on==137||on==240) return se_light(-1,row,a,g_use_slot);
    if(on==43){ g_se_on=SEON_BELL; g_se_on_actor=row>=0?(g_ow.inv[row].owner?g_ow.inv[row].owner:1):a; g_se_on_idx=-1; g_se_on_row=row; g_next_verb='X'; return 0; }
    if(on>=86&&on<=88){ int ac=(g_show_inv&&g_status_actor>=1)?g_status_actor:use_actor(), own=row>=0?(g_ow.inv[row].owner?g_ow.inv[row].owner:1):a; return se_totem(on,own==ac); }
    if(on==6 && row>=0) return se_gem(-1,row,g_ow.inv[row].owner?g_ow.inv[row].owner:1);
    if(on==10 && row>=0) return se_ribbon(-1,row,g_ow.inv[row].owner?g_ow.inv[row].owner:1);
    if(on==49) return se_notebook();
    if((on==59||on==60) && row>=0) return se_grind(-1,row);
    if(on==92) return se_unfold(-1);
    if(on==131 && row>=0) return se_dig(g_ow.inv[row].owner?g_ow.inv[row].owner:1);
    if(on==47 && row>=0) return se_bait(w,-1,row);
    if(on==95 && row>=0){ se_use_up(-1,row,1); if(g_alcohol<255) g_alcohol++; msgcat(0,"\nYou drink it."); return 1; }
    if(on==51 && row>=0) return se_camera(-1,row,g_ow.inv[row].owner?g_ow.inv[row].owner:1);
    if(on==50) return se_flintlock(-1,row,a);
    if(on==25||on==44||on==52||on==29||on==119){ g_se_on=(on==29||on==119)?SEON_HAMMER:SEON_KNIFE; g_se_on_actor=row>=0?(g_ow.inv[row].owner?g_ow.inv[row].owner:1):a; g_next_verb='X'; return 0; }
    if(on==136 && row>=0) return se_bucket(-1,row);
    if(on==190 && row>=0) return se_head(-1,row,g_ow.inv[row].owner?g_ow.inv[row].owner:1);
    if(on==192 && row>=0) return se_clay(-1,row,g_ow.inv[row].owner?g_ow.inv[row].owner:1);
    if(on==208 && row>=0) return se_torch(-1,row,a);
    if(on==252 && row>=0){ g_se_on=SEON_CRYSTAL; g_se_on_actor=g_ow.inv[row].owner?g_ow.inv[row].owner:1; g_se_on_idx=-1; g_se_on_row=row; g_next_verb='X'; return 0; }
    if(on==212) return se_fish(row>=0?(g_ow.inv[row].owner?g_ow.inv[row].owner:1):a);
    if(on==209){ g_se_on=SEON_LTORCH; g_se_on_actor=row>=0?(g_ow.inv[row].owner?g_ow.inv[row].owner:1):a; g_next_verb='X'; return 0; }
    if(on==204 && row>=0){ g_se_on=SEON_POWDER; g_se_on_actor=g_ow.inv[row].owner?g_ow.inv[row].owner:1; g_se_on_idx=-1; g_se_on_row=row; g_next_verb='X'; return 0; }
    if(on==191 && row>=0){ g_se_on=SEON_TARSTRIP; g_se_on_actor=g_ow.inv[row].owner?g_ow.inv[row].owner:1; g_se_on_idx=-1; g_se_on_row=row; g_next_verb='X'; return 0; }
    if(on==177 && row>=0) return se_sift(g_ow.inv[row].owner?g_ow.inv[row].owner:1);
    if(on==134 && row>=0){ g_se_on=SEON_STRIPS; g_se_on_actor=g_ow.inv[row].owner?g_ow.inv[row].owner:1; g_se_on_idx=-1; g_se_on_row=row; g_next_verb='X'; return 0; }
    if(on==94 && row>=0){ g_se_on=SEON_EXTING; g_se_on_actor=g_ow.inv[row].owner?g_ow.inv[row].owner:1; g_next_verb='X'; return 0; }
    if(on==63 && row>=0){ g_se_on=SEON_PLACHTA; g_se_on_actor=g_ow.inv[row].owner?g_ow.inv[row].owner:1; g_se_on_idx=-1; g_se_on_row=row; g_next_verb='X'; return 0; }
    if(on==42 && row>=0){ g_se_on=SEON_VINE; g_se_on_actor=g_ow.inv[row].owner?g_ow.inv[row].owner:1; g_se_on_idx=-1; g_se_on_row=row; g_next_verb='X'; return 0; }
    if(se_is_food(on) && row>=0){ msgcat(0,"\nYou eat the food."); se_use_up(-1,row,0); return 1; }
    { char nm[40]; int n=msgcat(0,"Nothing happens with the "); obj_name(row>=0?g_ow.inv[row].tile:(uint16_t)basetile(on),nm,sizeof nm); n=msgcat(n,nm); msgcat(n,"."); }   /* the cases not yet read (§3) */
    return 0;
}

/* U)se an object; if its tile (frame) changed (a door/container opened/closed/unlocked), mark it
 * DIRTY so do_save re-serialises the new frame into the save (in-place, nuvie_save.md). Per-game USE
 * is the game layer's use hook (game_layer.md). */
static int use_object(int idx)
{
    uint16_t t0 = g_wobj[idx].tile;
    int r;
    if(g_gl->use) r = g_gl->use(idx);                         /* the game's use switch (game_layer.md) */
    else { msgcat(0,"Nothing happens."); r = 0; }            /* MD: none until its GAME.EXE is read */

    if(g_wobj[idx].tile != t0) g_wobj[idx].dirty = 1;
    return r;
}

/* G)et gold coins: they join the shared gold pool (what merchants count and the save writes back as
 * coins), not an inventory stack the pool never sees (usecode_use.md). 1 = taken. */
/* what the party has, in coins */
static int gold_total(void)
{   if(g_gl->gold_pool) return g_cg.gold;
    { int t=0; for(int p=0;p<g_nparty;p++){ int a=g_party[p].actor; for(int i=0;i<g_ow.ninv;i++) if(ON_IS(g_ow.inv[i].obj_n,g_wko.gold)&&(g_ow.inv[i].owner?g_ow.inv[i].owner:1)==a) t+=g_ow.inv[i].qty; } return t; } }
static void gold_add(int n)
{   if(g_gl->gold_pool){ g_cg.gold+=n; return; }
    if(n>0){ g_add_to=1; inv_add_objn(g_wko.gold,n); } else pack_take(1,g_wko.gold,-n); }
static int take_gold(int idx){
    if(!g_wko.gold || g_wobj[idx].obj_n!=g_wko.gold || !g_gl->gold_pool) return 0;
    uint16_t q=g_wobj[idx].qty; if(!q) q=1;
    int t=g_cg.gold+(int)q; g_cg.gold=(t>0x7fffffff)?0x7fffffff:t;
    g_wobj[idx].alive=0; g_wobj[idx].dirty=1;
    return 1; }
static int theft_counts(const world_t*w,int idx); static void theft_done(world_t*w,int idx);   /* usecode_use.md (Theft) */
/* run a verb ('L'/'G'/'U') against the tile (dx,dy) from the avatar. */
/* --- readable text: books / signs / plaques / tombstones (docs/formats/strings.md) --------- */
/* readable object numbers: BOOK 151, SCROLL 152, TOMBSTONE 255, GRAVE 266, SIGN 332, SIGN_ARROW 333. */
static const int READABLE_OBJN[]={151,152,255,266,332,333};
static int is_readable_objn(int on){
    for(unsigned i=0;i<sizeof READABLE_OBJN/sizeof*READABLE_OBJN;i++) if(READABLE_OBJN[i]==on) return 1;
    return 0;
}

/* Food/drink obj_n, DERIVED from the shipped LOOK name table (docs/rules/usecode_use.md §Food):
 * 1 = eat, 2 = drink. Excludes reagents (garlic/nightshade), potions, and containers (jars/buckets).
 * U6's hunger model isn't implemented, so USE is the authentic "consume one + message" (no HP change).
 * Probable (name-derived); not cross-checked against Nuvie's use_food registration (no source on hand). */
/* where a lowered bridge reaches the far bank (usecode_use.md) */
static int bridge_end_tile(const world_t*w,int x,int y){ int t=world_tile(w,x,y); return t==16||t==28||t==32||t==44||t==214; }
static int can_store(int ci,int i); static void contain_obj(int i,int ci); static int tile_support(int t); static void missile_fly(const world_t*w,int sx,int sy,int tx,int ty,int mis,int*lx,int*ly);
static int drop_holder(int ci){ int con=g_wobj[ci].obj_n, fr=(int)g_wobj[ci].tile-basetile(con); return con==99||con==188||con==191||con==62||((con==98||con==186||con==192)&&fr==0); }
static int drop_surface(int x,int y){ int b=((y>>4)&(OBKT-1))*OBKT+((x>>4)&(OBKT-1));
    for(int k=g_obkt_start[b];k<g_obkt_start[b+1];k++){ const wobj_t*o=&g_wobj[g_obkt_idx[k]]; if(o->alive&&o->x==x&&o->y==y&&tile_support(o->tile)) return 1; } return 0; }
static int is_food_objn(int on){
    switch(on){
        case 95: case 96: case 128: case 129: case 130: case 131: case 132:  /* grapes,butter,bread,meat-portion,rolls,cake,cheese */
        case 133: case 135: case 180: case 184: case 209: case 210: case 265: return 1;   /* ham,chops,milk,honey,meat,ribs,fish */
        case 115: case 116: case 117: return 2;                              /* wine,mead,ale (drink) */
        default: return 0;
    }
}

/* Modal paged view of readable text, word-wrapped over the papyrus page. Any key pages forward;
 * Esc closes. `txt` is `len` bytes (NOT NUL-terminated); '\n' forces a line break. */
static void book_view(const char*txt,int len)
{
    enum { CX=16, CY=18, LNH=10, COLS=36, MAXLINES=96 };
    static char ln[MAXLINES][COLS+2]; int nl=0,c=0; ln[0][0]=0;
    for(int i=0;i<len && nl<MAXLINES;){
        if(txt[i]=='\n'){ ln[nl][c]=0; if(++nl<MAXLINES) ln[nl][0]=0; c=0; i++; continue; }
        while(i<len && txt[i]==' ') i++;                          /* collapse leading spaces */
        int ws=i; while(i<len && txt[i]!=' ' && txt[i]!='\n') i++;
        int wl=i-ws; if(wl>COLS) wl=COLS;                         /* clamp an over-long word */
        if(c>0 && c+1+wl>COLS){ ln[nl][c]=0; if(++nl>=MAXLINES) break; ln[nl][0]=0; c=0; }
        if(c>0) ln[nl][c++]=' ';
        for(int k=0;k<wl && c<COLS;k++) ln[nl][c++]=txt[ws+k];
        ln[nl][c]=0;
    }
    if(c>0) nl++;
    if(nl==0) nl=1;
    int per=(LH-CY-14)/LNH; if(per<1) per=1;                       /* text lines per page */
    if(g_bot) return;
    { int gk,gd=0; while((gk=plat_input_raw())&&++gd<64){(void)gk;} }  /* flush stale keys */
    for(int pg=0; pg*per<nl; pg++){
        blit_paper();                                             /* the papyrus page */
        for(int r=0;r<per && pg*per+r<nl;r++) ui_text(CX, CY+r*LNH, ln[pg*per+r], 0);  /* dark ink */
        const char*ft=((pg+1)*per<nl)?"(space to turn the page)":"(done)";
        ui_text((LW-ui_textw(ft))/2, LH-12, ft, 0x3e);
        rdr_present_doubled(LH);
        int k; while(!(k=plat_input_raw())) vsync_pump();
        if((k&0xFF)==0x1b) break;                                 /* Esc closes early */
    }
}

/* read a readable world object: entry = quality-1 (quality 0 => entry 126, strings.md). */
static void read_object(int idx)
{
    int q=g_wobj[idx].quality, e = q>0 ? q-1 : 126;
    if(e>=0 && e<g_nbook && g_book[e] && g_booklen[e]>0){ book_view(g_book[e], g_booklen[e]); msgcat(0,"Thou readest it."); }
    else msgcat(0,"Nothing is written here.");
}

/* --- map-overview render (Peer / Wizard Eye, magic_skills.md §5). Draws an 88x88-tile region
 * centred on (cx,cy) into the 176x176 map window at 2 px/tile: each tile = its terrain tile's
 * centre pixel; actors are dots (party bright, others grey); the view centre is a yellow cross. */
static void overview_render(const world_t*w,int cx,int cy)
{
    enum { R=44 };                                     /* 88 tiles across * 2 px = 176 = MAPSZ */
    for(int oy=0;oy<88;oy++){
        uint8_t*r0=ROW(MAPY+oy*2)+MAPX, *r1=ROW(MAPY+oy*2+1)+MAPX;
        for(int ox=0;ox<88;ox++){
            int wx=(cx-R+ox)&(U6_SURFACE_TILES-1), wy=(cy-R+oy)&(U6_SURFACE_TILES-1);
            int t=world_tile(w,wx,wy); uint8_t col=g_tileset[(int32_t)t*256+8*16+8];
            if(col==TILE_TRANSPARENT) col=0;
            r0[ox*2]=col; r0[ox*2+1]=col; r1[ox*2]=col; r1[ox*2+1]=col;
        }
    }
    for(int i=1;i<U6_MAX_ACTORS;i++){ int ax,ay; if(g_ainvis[i]) continue; if(!actor_pos(i,&ax,&ay)) continue;
        int ddx=((ax-cx+512)&(U6_SURFACE_TILES-1))-512, ddy=((ay-cy+512)&(U6_SURFACE_TILES-1))-512;
        if(ddx<-R||ddx>=R||ddy<-R||ddy>=R) continue;
        uint8_t col=(i==1||is_party_member(i))?15:8;   /* party white, others grey */
        ROW(MAPY+(ddy+R)*2)[MAPX+(ddx+R)*2]=col; }
    int mx=MAPX+R*2, my=MAPY+R*2;                        /* view centre = a yellow cross */
    ROW(my)[mx-1]=14; ROW(my)[mx]=14; ROW(my)[mx+1]=14; ROW(my-1)[mx]=14; ROW(my+1)[mx]=14;
}
/* Modal overview. pannable=0 (Peer): any key closes. pannable=1 (Wizard Eye): arrows scout, Esc closes. */
static void overview_view(const world_t*w,int cx,int cy,int pannable)
{
    { int gk,gd=0; while((gk=plat_input_raw())&&++gd<64){(void)gk;} }   /* flush stale keys */
    for(;;){
        overview_render(w,cx,cy);
        const char*cap=pannable?"Wizard Eye - arrows scout, Esc ends":"Peer - press a key";
        ui_text(MAPX+(MAPSZ-ui_textw(cap))/2, MAPY+MAPSZ-9, cap, 14);
        rdr_present_doubled(LH);
        int k; while(!(k=plat_input_raw())) vsync_pump();
        int ch=k&0xFF, sc=(k>>8)&0xFF;
        if(!pannable || ch==0x1b || ch==13) break;
        if(sc==0x48) cy=(cy-2)&(U6_SURFACE_TILES-1); else if(sc==0x50) cy=(cy+2)&(U6_SURFACE_TILES-1);
        else if(sc==0x4b) cx=(cx-2)&(U6_SURFACE_TILES-1); else if(sc==0x4d) cx=(cx+2)&(U6_SURFACE_TILES-1);
    }
}


/* ===================== VEHICLES: skiff / ship / horse (docs/rules/vehicles.md) =====================
 * The boats stay ordinary map objects; boarding attaches the player to them (no "vehicle actor").
 * Water = tileflags1 bit0 (Wet) of the ORIGINAL map tile (the pack's U6WG section); the ship is
 * additionally barred from the shoreline tile band 16..47 (§2). Surface only. */
static int      g_veh_kind;          /* 0 none / 414 skiff / 412 ship / 431 mounted horse */
static int      g_veh_o[3];          /* wobj indices: [0] skiff-or-CENTRE, [1] front, [2] back */
static int      g_veh_face;          /* 0 N, 1 E, 2 S, 3 W (§1)                            */
static int      g_veh_phase;         /* frame animation phase (toggles per step)            */
static uint8_t  g_veh_pz[MAXPARTY];  /* hidden party members' saved z (aboard a boat)       */
static int      g_veh_horse=-1;      /* the absorbed horse's actor id while mounted         */
static uint8_t  g_veh_hz;            /* its saved z                                          */
static int      g_horse_moved=-1;    /* last horse actor left somewhere new (dismount) -> its position is saved */

static int g_tmpdm_invalidate(void){ g_tmp_valid=0; g_dm_valid=0; return 0; }   /* teleport: full view rebuild */
static int veh_aboard(void){ return g_veh_kind==412||g_veh_kind==414||g_veh_kind==415||g_veh_kind==423||g_veh_kind==237; }   /* in a vessel (not a horse); 237 = SE's raft (se_use.md §5w) */
static int ship_aboard(void){ return g_veh_kind==412; }
static int use_transition_object(world_t *w, int idx);   /* ladders/holes (defined with the level code below) */
static int npc_at(const world_t*w,int x,int y);           /* (defined with the NPC code below) */
static int step_triggers(world_t *w);
static void eggs_update(const world_t *w, int teleport); /* eggs.md §2 (defined with the egg code below) */
static void eggs_load_level(const uint8_t *d, int32_t n, int level);
static void temp_actors_clear(void);

/* Boats are the only map objects that MOVE. Their save records are located by position
 * (save_load.md §5), so each boarded part remembers where its record still says it is; do_save
 * patches the record there and re-anchors it. Cleared by a load (positions match the save again). */
#define MOVED_MAX 24
static struct { uint16_t idx, ox, oy, oon; } g_moved[MOVED_MAX];
static int g_nmoved;
static void moved_register(int idx)
{   if(idx<0) return;
    for(int k=0;k<g_nmoved;k++) if(g_moved[k].idx==(uint16_t)idx) return;
    if(g_nmoved<MOVED_MAX){ g_moved[g_nmoved].idx=(uint16_t)idx; g_moved[g_nmoved].oon=g_wobj[idx].obj_n;
        g_moved[g_nmoved].ox=g_wobj[idx].x; g_moved[g_nmoved].oy=g_wobj[idx].y; g_nmoved++; } }

static const signed char VDX[4]={0,1,0,-1}, VDY[4]={-1,0,1,0};      /* N E S W (§3 exit order) */
static int veh_face_of(int dx,int dy){ if(dy<0)return 0; if(dy>0)return 2; return dx>0?1:3; }

static int tile_is_water(const world_t*w,int x,int y)
{ return w->level==0 && (g_tflags1[world_tile(w,x,y)]&1); }
/* an object on the target tile blocks a vehicle (§2) — our own parts excluded (they move too) */
static int veh_obj_blocks(int x,int y)
{   int i=objworld_at(&g_ow, x&(U6_SURFACE_TILES-1), y&(U6_SURFACE_TILES-1));
    if(i<0) return 0;
    if(g_veh_kind) for(int k=0;k<3;k++) if(i==g_veh_o[k]) return 0;
    return 1; }
static int veh_can_enter(const world_t*w,int x,int y,int deep)
{   if(!tile_is_water(w,x,y)) return 0;
    if(deep){ int t=world_tile(w,x,y); if(t>=16 && t<=47) return 0; }   /* ship: open water only */
    return !veh_obj_blocks(x,y); }

/* re-derive the part frames from facing + phase (§1: front 0-7, centre 8-15, back 16-23) */
static void veh_set_tiles(void)
{   if(g_veh_kind==414){ wobj_t*o=&g_wobj[g_veh_o[0]];
        o->tile=(uint16_t)(basetile(414)+g_veh_face); o->dirty=1; }   /* four tiles, one per facing (vehicles.md §1) */
    else if(g_veh_kind==415||g_veh_kind==423){ wobj_t*o=&g_wobj[g_veh_o[0]]; if(!o->dirty) o->dirty=WOBJ_DIRTY_STATE; }   /* raft / balloon: one frame (a never-saved inflated balloon stays DROPPED) */
    else if(g_veh_kind==412){ int bt=basetile(412);
        g_wobj[g_veh_o[1]].tile=(uint16_t)(bt+   g_veh_face*2+g_veh_phase);
        g_wobj[g_veh_o[0]].tile=(uint16_t)(bt+ 8+g_veh_face*2+g_veh_phase);
        g_wobj[g_veh_o[2]].tile=(uint16_t)(bt+16+g_veh_face*2+g_veh_phase);
        for(int k=0;k<3;k++) g_wobj[g_veh_o[k]].dirty=1; } }

/* party sprites vanish into the vehicle (§3.6) and reappear at the landing tile */
static void veh_hide_party(void)
{   for(int p=0;p<g_nparty && p<MAXPARTY;p++){ int a=g_party[p].actor;
        if(a<=1||a>=U6_MAX_ACTORS){ g_veh_pz[p]=0; continue; }
        g_veh_pz[p]=g_actz[a]; g_actz[a]=0xff; }
    g_avatar_hide=1; }
static void veh_show_party(const world_t*w,int lx,int ly)
{   for(int p=0;p<g_nparty && p<MAXPARTY;p++){ int a=g_party[p].actor;
        if(a<=1||a>=U6_MAX_ACTORS) continue;
        g_actz[a]=g_veh_pz[p]; g_actx[a]=(uint16_t)lx; g_acty[a]=(uint16_t)ly; }
    (void)w; g_avatar_hide=0; }

static int wobj_boat_at(int obj_n,int x,int y)
{   for(int i=0;i<g_ow.nobjs;i++){ const wobj_t*o=&g_wobj[i];
        if(o->alive && o->obj_n==(uint16_t)obj_n && o->x==(uint16_t)(x&(U6_SURFACE_TILES-1))
           && o->y==(uint16_t)(y&(U6_SURFACE_TILES-1))) return i; }
    return -1; }

/* (U)se while aboard: disembark next to land, N/E/S/W (§3.1). Returns recompose. */
static int vehicle_exit(world_t*w)
{   for(int d=0;d<4;d++){
        int lx=(w->px+VDX[d])&(U6_SURFACE_TILES-1), ly=(w->py+VDY[d])&(U6_SURFACE_TILES-1);
        if(world_is_passable(w,lx,ly) && !tile_is_water(w,lx,ly)){   /* land: not a boat moored on water (§3.1) */
            veh_show_party(w,lx,ly);
            g_veh_kind=0; g_avatar_ovr=0;
            w->px=(uint16_t)lx; w->py=(uint16_t)ly;
            (void)g_tmpdm_invalidate();
            msgcat(0,"You disembark.");
            return 1; } }
    msgcat(0,"Only next to land.");
    return 1; }

/* passthrough (278 vertical / 280 horizontal; usecode_use.md): opening moves it one tile up / left */
static int use_passthrough(world_t*w,int idx)
{   wobj_t*o=&g_wobj[idx]; int fr=(int)o->tile-basetile(o->obj_n), span=(w->level==0)?U6_SURFACE_TILES:256;
    int nx=o->x, ny=o->y, nfr;
    if(fr<2){ if(o->obj_n==278) ny=(ny-1)&(span-1); else nx=(nx-1)&(span-1); nfr=2; }
    else     { if(o->obj_n==278) ny=(ny+1)&(span-1); else nx=(nx+1)&(span-1); nfr=0; }
    if(fr>=2 && (npc_at(w,nx,ny)>=0 || (nx==(int)w->px && ny==(int)w->py))){ msgcat(0,"Not now!"); return 1; }
    moved_register(idx); o->x=(uint16_t)nx; o->y=(uint16_t)ny; o->tile=(uint16_t)(basetile(o->obj_n)+nfr);
    if(o->dirty!=WOBJ_DIRTY_DROPPED) o->dirty=WOBJ_DIRTY_STATE; build_blocked();
    msgcat(0, nfr==2?"Open the passthrough.":"Close the passthrough."); return 1; }

/* (U)se a skiff/ship object: board it (§3 checks in order). Returns recompose. */
static int use_boat(world_t*w,int idx)
{   wobj_t*o=&g_wobj[idx]; int on=o->obj_n;
    if((on==414||on==415) && !tile_is_water(w,o->x,o->y)){ msgcat(0,"You must place it in water first."); return 1; }
    int ci=idx;
    if(on==412){                                   /* any part -> the CENTRE object (§3.3) */
        int fr=(int)o->tile-basetile(412), face=(fr&7)/2, cx=o->x, cy=o->y;
        if(fr<8){ cx-=VDX[face]; cy-=VDY[face]; }             /* front: centre lies behind  */
        else if(fr>=16){ cx+=VDX[face]; cy+=VDY[face]; }      /* back:  centre lies ahead   */
        ci=wobj_boat_at(412,cx,cy);
        if(ci<0){ msgcat(0,"Ship not usable."); return 1; }
        { int cf=(int)g_wobj[ci].tile-basetile(412);
          if(cf<8||cf>=16){ msgcat(0,"Ship not usable."); return 1; } } }
    wobj_t*c=&g_wobj[ci];
    if(c->quality!=0){                             /* for sale: needs the matching SHIP DEED (§3.4) */
        if(!objworld_has(&g_ow,149,c->quality)){ msgcat(0,"A deed is required."); return 1; }
        c->quality=0; c->dirty=1; }
    int face=on==414?(((int)c->tile-basetile(on))&3):(((int)c->tile-basetile(on))&7)/2, fi=-1, bi=-1;   /* a skiff's frame is its facing (§1) */
    if(on==412){
        fi=wobj_boat_at(412,c->x+VDX[face],c->y+VDY[face]);
        bi=wobj_boat_at(412,c->x-VDX[face],c->y-VDY[face]);
        if(fi<0||bi<0){ msgcat(0,"Ship not usable."); return 1; } }
    g_veh_kind=on; g_veh_o[0]=ci; g_veh_o[1]=fi; g_veh_o[2]=bi; g_combat_mode=0;   /* boarding breaks off combat (music_areas.md §2) */
    moved_register(ci); moved_register(fi); moved_register(bi);   /* their records stay findable after sailing */
    g_veh_face=face; g_veh_phase=0;
    w->px=c->x; w->py=c->y;                        /* the player now IS the vehicle (camera follows) */
    veh_hide_party();
    (void)g_tmpdm_invalidate();
    msgcat(0,on==412?"You board the ship.":on==415?"You board the raft.":"You board the skiff.");
    return 1; }
/* the balloon (wind.md §4): U)se the inflated balloon (423) to board — any terrain */
static int use_balloon(world_t*w,int idx)
{   wobj_t*c=&g_wobj[idx];
    g_veh_kind=423; g_veh_o[0]=idx; g_veh_o[1]=g_veh_o[2]=-1; moved_register(idx); g_combat_mode=0;
    g_veh_face=2; g_veh_phase=0;
    w->px=c->x; w->py=c->y;
    veh_hide_party(); (void)g_tmpdm_invalidate();
    msgcat(0,"You board the balloon."); return 1; }
/* aboard the balloon, U)se: land on adjacent passable ground; the balloon deflates into the
 * carried-balloon object (420) lying at the landing tile (its record is retyped on save) */
static int balloon_land(world_t*w)
{   for(int d=0;d<4;d++){
        int lx=(w->px+VDX[d])&(U6_SURFACE_TILES-1), ly=(w->py+VDY[d])&(U6_SURFACE_TILES-1);
        if(world_is_passable(w,lx,ly)){
            wobj_t*b=&g_wobj[g_veh_o[0]];
            b->obj_n=420; b->tile=(uint16_t)basetile(420); b->x=(uint16_t)lx; b->y=(uint16_t)ly;
            if(b->dirty!=WOBJ_DIRTY_DROPPED) b->dirty=WOBJ_DIRTY_STATE;   /* never saved since inflating: still the carried record, relocated */
            veh_show_party(w,lx,ly);
            g_veh_kind=0; g_avatar_ovr=0;
            w->px=(uint16_t)lx; w->py=(uint16_t)ly;
            build_blocked(); (void)g_tmpdm_invalidate();
            msgcat(0,"You land; the balloon deflates.");
            return 1; } }
    msgcat(0,"Only next to land.");
    return 1; }
/* U)se of a carried item (wind.md §1/§4): the fan turns the wind; the balloon inflates beside us */
/* buckets (usecode_use.md): a well / a cow fills an empty bucket (178) with water (179) / milk (180) */
static int use_actor(void){ return g_solo_on&&g_solo_m>0?g_solo_m:g_nparty?g_party[0].actor:1; }   /* who acts */
static int use_actor_fwd(void){ return use_actor(); }
static int carry_over(int a,int extra){ return g_weights && (int32_t)g_astr[a]*20<actor_carried(a)+extra; }   /* over the limit, in 0.1 stones */
static int fill_bucket(int filled)
{
    if(objworld_count(&g_ow,178)<=0){ msgcat(0,"You need a bucket."); return 0; }
    if(carry_over(use_actor(),32)){ msgcat(0,filled==179?"The bucket of water is too heavy for you.":"The bucket of milk is too heavy for you."); return 0; }
    objworld_consume(&g_ow,178,1); inv_add_objn(filled,1); msgcat(0,"Done"); return 1;
}
