                dbg_num("PU spell gettable=", objworld_can_get(&g_ow,58)); dbg_num("PU moonstone gettable=", objworld_can_get(&g_ow,73));
                int ch=temp_obj_new(98,0,ex2,ey,0);                         /* an open chest */
