              SC_NUM("bag row",b); g_inv_sel=m; g_status_actor=1; g_show_inv=1; pack_move_into(&w,b); SC_MSG(); SC_NUM("meat in the bag",g_ow.inv[m].in==g_ow.inv[b].id&&g_ow.inv[b].id);
