                    dbg_num("MT double-sized object found=", big>=0); if(big>=0){ dbg_num("MT  its obj=", g_wobj[big].obj_n); dbg_num("MT bird may enter it=", mover_can_enter(&w,g_wobj[big].x,g_wobj[big].y)); }
